export type IUserContainer = IContainer & {
	-- 用户ID
	getUserId: (self: IUserContainer) -> number,

	-- 启动容器内事务
	Start: (self: IUserContainer) -> (),

	-- 停止容器内事务
	Stop: (self: IUserContainer) -> (),

	-- 设置上下文数据
	SetContext: (self: IUserContainer, key: string, valueHandler: () -> any) -> (),

	-- 获取上下文数据
	GetContext: (self: IUserContainer, key: string) -> any,
}
